// Helper functions for Admin page
export const getTotalUsers = async () => {
  try {
    const { count, error } = await supabase
      .from('profiles')
      .select('*', { count: 'exact', head: true });
    
    if (error) throw error;
    return count || 0;
  } catch (error) {
    console.error("Error getting total users:", error);
    return 0;
  }
};

