export const getAllEvents = async () => {
  try {
    const { data, error } = await supabase
      .from('events')
      .select('*')
      .order('event_date', { ascending: false });
    
    if (error) throw error;
    return data || [];
  } catch (error) {
    console.error("Error getting all events:", error);
    return [];
  }
};

export const deleteEvent = async (eventId: string) => {
  try {
    // First delete from event_interested
    const { error: interestedError } = await supabase
      .from('event_interested')
      .delete()
      .eq('event_id', eventId);
      
    if (interestedError) throw interestedError;
    
    // Delete from event_attendees
    const { error: attendeesError } = await supabase
      .from('event_attendees')
      .delete()
      .eq('event_id', eventId);
      
    if (attendeesError) throw attendeesError;
    
    // Delete from events
    const { error } = await supabase
      .from('events')
      .delete()
      .eq('id', eventId);
      
    if (error) throw error;
    
    return true;
  } catch (error) {
    console.error("Error deleting event:", error);
    return false;
  }
};

export const promoteStudentToInfoOfficer = async (userId: string) => {
  try {
    // First check if the user already has an information_officer role
    const { data: existingRole, error: checkError } = await supabase
      .from('user_roles')
      .select('*')
      .eq('user_id', userId)
      .eq('role', 'information_officer')
      .maybeSingle();
      
    if (checkError) throw checkError;
    
    if (existingRole) {
      // User already has this role, no need to insert
      return true;
    }
    
    // Add information_officer role
    const { error: insertError } = await supabase
      .from('user_roles')
      .insert({ user_id: userId, role: 'information_officer' });
      
    if (insertError) throw insertError;
    
    return true;
  } catch (error) {
    console.error("Error promoting student:", error);
    return false;
  }
};
